import {sagaLevelCapV25} from './saga-stats-v25.js';
import {MERCENARY_ROSTER} from './mercenary-v14.js';
import {MERCENARY_QUALITIES_V18} from './mercenary-quality-v18.js';
import {EQUIPMENT_SLOTS,SLOT_NAMES,equipmentPlan,weaponHands,WEAPON_RULES} from './equipment-v14.js';
import {ATTRIBUTE_HELP,CLASS_TRAITS,CLASS_GROWTH,totalAttributes,attributeParts,UNIQUE_EFFECTS} from './growth-v14.js';
import {AFFIXES} from './data-v14.js';
import {enchantDescription} from './enchantments-v14.js';
import {drawIdentityActorV18} from './identity-visuals-v18.js';

const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attrNames={str:'力量',dex:'敏捷',vit:'体质',wis:'精神'};
const gearQualities={common:['普通','#c6c9cb'],uncommon:['精良','#8bc09b'],rare:['稀有','#85bada'],epic:['史诗','#bb97d6'],legendary:['传奇','#e5ad65'],abyssal:['黑曜','#777b87']};
const button=(action,label,arg='',arg2='',disabled=false,cls='',extra='')=>`<button class="${cls}" data-merc="${action}" data-merc-arg="${escape(arg)}" data-merc-arg2="${escape(arg2)}"${disabled?' disabled':''}${extra?' '+extra:''}>${label}</button>`;
const uiStates=new WeakMap();
const local=g=>{if(!uiStates.has(g))uiStates.set(g,{actor:null,activeSlot:0,confirm:null,notice:''});return uiStates.get(g);};
const template=p=>MERCENARY_ROSTER[p?.templateId||p?.mercenaryId];
const quality=p=>MERCENARY_QUALITIES_V18[p?.quality]||MERCENARY_QUALITIES_V18.common;
const className=(g,p)=>g._mercenaryDeps.CLASSES[p.cls]?.name||p.cls;
const contractSuffix=p=>p?.mercenaryId?.includes('~')?' · '+p.mercenaryId.split('~')[1]+'号契约':'';
const status=(h,p)=>p.downed?'负伤休整':h.activeIds.includes(p.mercenaryId)?'正在同行':'城中待命';
function chosen(g){const h=g.mercenaryState(),id=h.selectedId&&h.roster[h.selectedId]?h.selectedId:Object.keys(h.roster)[0];return {h,id,p:h.roster[id]};}
function syncActor(g,id){const u=local(g);if(u.actor!==id){u.actor=id;u.activeSlot=0;u.confirm=null;u.notice='';}return u;}
function imagePortrait(p,helpers,cls=''){const src=helpers.portrait?.(template(p)?.name||p.name);return src?`<img class="${cls}" src="${escape(src)}" alt="${escape(p.name)}的画像" draggable="false">`:'';}
function figure(p,helpers,portrait=false){const art=portrait?imagePortrait(p,helpers,'portrait-art'):'';return art||`<canvas id="mercenary-paperdoll" width="360" height="430" aria-label="${escape(p.name)}当前装备外观"></canvas>`;}
const icon=(i,helpers)=>helpers.gearIcon?.(i)||'<span class="vacant-icon">＋</span>';
const skillIcon=(k,helpers,p)=>helpers.iconHTML?.(k,p.cls)||'';
function paperdoll(g,p,helpers){const h=g.mercenaryState();return `<div class="paperdoll"><div class="paperdoll-person">${figure(p,helpers)}<strong>${escape(p.name)}</strong><small>${escape(className(g,p))} · Lv.${p.level}</small></div>${EQUIPMENT_SLOTS.map(slot=>{const item=p.gear[slot],id=item?.id||'empty:'+slot;return button('gear',`<small>${SLOT_NAMES[slot]}</small>${icon(item,helpers)}<span>${escape(item?.name||(slot==='offhand'&&weaponHands(p.gear.weapon)===2?'双手武器占用':'未装备'))}</span>`,id,'',false,`equip-slot slot-${slot} ${item?.rarity||''} ${h.gear===id?'chosen':''}`,`aria-label="查看${SLOT_NAMES[slot]}装备位"`);}).join('')}</div>`;}
function equipmentDetail(g,p,selected,safe,helpers){
 if(!selected)return '<div class="detail-empty">选择行囊或身上的装备<br><small>查看属性、附魔与替换后的变化</small></div>';
 const {i,slot,worn}=selected,before=g._mercenaryDeps.stats(p),w=['weapon','offhand'].includes(i.slot),targets=w&&weaponHands(i)===1?['weapon','offhand']:[i.slot];
 const actions=targets.map(target=>{const plan=equipmentPlan(p,i,target),after=plan?g._mercenaryDeps.stats({...p,gear:plan.gear}):null,full=!!plan&&g.p.bag.length-1+plan.removed.length>60;return `<div class="gear-target"><strong>${SLOT_NAMES[target]}</strong>${after?`<small>攻击 ${after.atk>=before.atk?'+':''}${(after.atk-before.atk).toFixed(1)} · 生命 ${after.hp>=before.hp?'+':''}${after.hp-before.hp}</small>`:''}${button('equip',i.minLevel>p.level?'需要 Lv.'+i.minLevel:full?'行囊需要空位':'装备到'+SLOT_NAMES[target],p.mercenaryId,i.id+'|'+target,!safe||!plan||full)}</div>`;}).join('');
 return `<article class="item ${i.rarity||''}"><div class="item-heading">${icon(i,helpers)}<div><small>${SLOT_NAMES[i.slot]||'装备'} / ${gearQualities[i.rarity]?.[0]||'普通'}${worn?' · 已装备':''}</small><h3>${escape(i.name)}</h3></div></div><p>需要 Lv.${i.minLevel||1} · ${w?escape(WEAPON_RULES[i.weaponType]?.label||'武器')+' · ':''}攻击 +${Math.round(i.atk||0)}　生命 +${Math.round(i.hp||0)}</p>${i.attrs?`<p>${Object.entries(i.attrs).map(([k,v])=>`${attrNames[k]||escape(k)} +${v}`).join('　')}</p>`:''}${w?`<p class="muted">${weaponHands(i)===2?'占用主、副武器两处。换装时，副武器收进行囊。':'可以装备到任意武器位；副手提供50%武器攻击、完整属性与附魔。'}</p>`:''}${[i.hellRouteDescription,i.activityGearDescriptionV17,i.uniqueEffect&&UNIQUE_EFFECTS[i.uniqueEffect],i.affix&&AFFIXES[i.affix]?.desc,i.setId&&('套装：'+(i.setName||i.setId))].filter(Boolean).map(t=>`<p class="affix">${escape(t)}</p>`).join('')}${i.careerId?'<p class="muted">专属转职词条需要对应路线。同行当前按基础职业战斗。</p>':''}${i.enchantment?`<p class="enchant-current">${escape(enchantDescription(i.enchantment))}</p>`:''}${worn?button('unequip',g.p.bag.length>=60?'行囊已满，暂不能卸下':'卸下，放回行囊',p.mercenaryId,slot,!safe||g.p.bag.length>=60):`<div class="gear-targets">${actions}</div>`}</article>`;
}
function equipmentView(g,p,safe,helpers){const h=g.mercenaryState(),all=[...Object.entries(p.gear).filter(([,i])=>i).map(([slot,i])=>({i,slot,worn:true})),...g.p.bag.map(i=>({i,slot:i.slot,worn:false}))],selected=all.find(({i})=>i.id===h.gear);return `<div class="inventory-workspace with-doll"><section class="doll-column">${paperdoll(g,p,helpers)}<p class="muted">正在整理 ${escape(p.name)} 的装备</p></section><section class="inventory-column"><div class="inventory-heading"><h3>携带装备</h3><small>${g.p.bag.length} / 60 · 全队共用行囊</small></div><div class="inventory-grid">${g.p.bag.map(i=>button('gear',icon(i,helpers),i.id,'',false,`inventory-cell ${i.rarity||''} ${h.gear===i.id?'chosen':''}`,`aria-label="查看${escape(i.name)}"`)).join('')}${Array.from({length:Math.max(0,12-g.p.bag.length)},()=>'<div class="inventory-cell empty-cell" aria-hidden="true"></div>').join('')}</div><div class="selected-detail" aria-live="polite">${equipmentDetail(g,p,selected,safe,helpers)}</div></section></div>`;}
function dismissal(g,p,safe){const u=local(g),info=g.mercenaryDismissInfoV23?.(p.mercenaryId);if(u.confirm?.id!==p.mercenaryId)return '';if(u.confirm.kind==='reset'){const item=u.confirm.item;return `<section class="companion-confirm-v23" role="group" aria-label="确认重置"><h3>重置${item==='attributeReset'?'属性加点':'技能加点'}？</h3><p>消耗 1 份${item==='attributeReset'?'澄心盐':'回响墨'}，只退还 ${escape(p.name)} 已投入的点数。</p><div class="row">${button('cancel-confirm','先不重置')}${button('confirm-reset','确认重置',p.mercenaryId,item,!safe,'primary')}</div></section>`;}
 const count=info?.equipmentCount??Object.values(p.gear).filter(Boolean).length,free=info?.freeSlots??Math.max(0,60-g.p.bag.length),enough=info?.canDismiss??(safe&&free>=count);return `<section class="companion-confirm-v23" role="group" aria-label="确认解雇"><h3>与 ${escape(p.name)} 结束同行？</h3><p>身上的 ${count} 件装备会全部收回行囊；这位同行的等级、加点与已学战技不会保留。招募券不退还。</p><p>${escape(info?.reason||(enough?'行囊空位足够，确认后再告别。':`行囊还需要腾出 ${Math.max(0,count-free)} 个空位，装备会留在同行身上。`))}</p><div class="row">${button('cancel-confirm','继续同行')}${button('confirm-dismiss','确认解雇',p.mercenaryId,'',!safe||!enough,'danger-v23')}</div></section>`;}
function attributesView(g,p,safe,helpers){const s=g._mercenaryDeps.stats(p),h=g.mercenaryState(),totals=totalAttributes(p),q=quality(p);return `<div class="attrs-layout"><div class="attribute-portrait companion-portrait-v23">${figure(p,helpers,true)}</div><div><article class="career-trait"><strong>${escape(className(g,p))} · ${escape(CLASS_TRAITS[p.cls]?.name||'')}</strong><p>${escape(CLASS_TRAITS[p.cls]?.desc||'')}</p><small style="color:${q.color}">${q.name}${contractSuffix(p)} · 品质成长已计入下方属性</small></article><p class="muted">生命 ${Math.ceil(p.hp)} / ${s.hp} · 法力 ${Math.floor(p.mp)} / ${s.mp}<br>攻击 ${Math.round(s.atk)} · 暴击 ${(s.crit*100).toFixed(1)}% · 普攻间隔 ${s.attackRate.toFixed(2)} 秒<br>减伤 ${(s.reduction*100).toFixed(1)}% · 移速 205 · 每秒回蓝 ${s.manaRegen.toFixed(2)}</p>${Object.entries(attrNames).map(([k,name])=>{const a=attributeParts(p,k);return `<div class="attr-row"><div><strong>${name}　${totals[k]}</strong><small>${escape(ATTRIBUTE_HELP[k])}<br>初始 ${a.initial} + 成长 ${a.growth} + 自分配 ${a.allocated}${a.gear?' + 装备 '+a.gear:''}</small></div>${button('allocate','＋ 加一点',p.mercenaryId,k,!safe||p.ap<1)}</div>`;}).join('')}<p class="tip">每级职业成长：${Object.entries(CLASS_GROWTH[p.cls]?.perLevel||{}).map(([k,v])=>attrNames[k]+' +'+v).join(' · ')}；另得 3 点自由属性与 1 点技能。品质另有成长加成，敏捷不增加移速。</p><div class="row">${h.activeIds.includes(p.mercenaryId)?button('withdraw','回城待命',p.mercenaryId,'',!safe):button('deploy',h.activeIds.length>=3?'出战人数已满':'一起出发',p.mercenaryId,'',!safe||p.downed||h.activeIds.length>=3)}${button('treat','包扎与休息 · 30金',p.mercenaryId,'',!safe||g.p.gold<30||!p.downed&&p.hp>=s.hp&&p.mp>=s.mp)}</div><div class="row companion-manage-v23">${button('request-reset','重置属性',p.mercenaryId,'attributeReset',!safe||!(g.p.items.attributeReset>0),'ghost')}${button('request-reset','重置技能',p.mercenaryId,'skillReset',!safe||!(g.p.items.skillReset>0),'ghost')}${button('dismiss','解雇',p.mercenaryId,'',!safe,'ghost')}</div>${dismissal(g,p,safe)}</div></div>`;}
function trainingReason(g,p,k,safe){const v=g._mercenaryDeps.SKILLS[k],rank=p.skills[k]||0;if(!safe)return '回到安全处后可调整';if(rank>=v.rank)return '已满级';if(p.level<Math.max(v.lv||1,rank+1))return '需要 Lv.'+Math.max(v.lv||1,rank+1);if(v.requires&&(p.skills[v.requires[0]]||0)<v.requires[1])return '需要先提升前置战技';if(p.sp<v.cost)return '技能点不足';return '';}
function studyView(g,p,safe,helpers){const info=g.mercenaryStudyInfoV23?.(p.mercenaryId),price=info?.price,result=info?.lastResult?.actorId===p.mercenaryId?info.lastResult:null;const last=result?`${p.name}${result.duplicate?'重读了':'领悟了'}「${g.mercenarySkillText(p.mercenaryId,result.skillId)?.name||g._mercenaryDeps.SKILLS[result.skillId]?.name||'战技'}」${result.duplicate?'，获得 '+result.insightGained+' 点研习心得'+(result.skillPointsGained?'，转为 '+result.skillPointsGained+' 点个人技能点':''):'。'}`:'';return `<section class="note-card companion-study-v23"><div class="item-heading">${helpers.miniItemIcon?.('mercenaryBook')||''}<div><small>持有 ${g.p.items.mercenaryBook||0} 卷</small><h3>同行研习卷</h3></div></div><p>交给 ${escape(p.name)} 研读，可能领悟新的战技，也可能读到已经掌握的招式。重复所得的研习心得只属于这位同行。</p>${Array.isArray(info?.odds)?`<details><summary>查看品质概率与研习规则</summary><p>${info.odds.map(o=>`${escape(o.name||gearQualities[o.quality]?.[0]||o.quality)} ${((o.probability??o.chance??0)*100).toFixed(1)}%`).join(' · ')}</p><p>普通 / 精良 / 稀有 / 史诗的重复战技分别增加 1 / 2 / 3 / 5 点心得；每 ${info.duplicateThreshold||5} 点换成 1 点个人技能点。当前心得 ${info.insight||0} / ${info.duplicateThreshold||5}。可研习的品质随本人等级开放。</p></details>`:''}${result?`<p class="companion-result-v23" role="status">${escape(last)}</p>`:''}<div class="row">${button('teach','交给 '+escape(p.name)+' 研读',p.mercenaryId,'',!safe||!(g.p.items.mercenaryBook>0))}${button('buyBook',Number.isFinite(price)?'购买研习卷 · '+price+'金':'购买研习卷',p.mercenaryId,'',!safe||!Number.isFinite(price)||g.p.gold<price)}</div></section>`;}
function skillsView(g,p,safe,helpers){const h=g.mercenaryState(),u=local(g),defs=g._mercenaryDeps.SKILLS,known=Object.keys(p.skills).filter(k=>p.skills[k]>0&&defs[k]),selected=known.includes(h.skill)?h.skill:known[0],info=selected?g.mercenarySkillText(p.mercenaryId,selected):null,groups=[['已掌握战技',known.filter(k=>!defs[k].passive)],['被动修行',known.filter(k=>defs[k].passive)]],slot=Math.min(u.activeSlot,p.activeSkills.length,4);return `<div class="summary"><span>可用技能点 <b>${p.sp}</b></span><span>已学 ${known.length} 项 · 激活 ${p.activeSkills.length} / 5</span></div><section class="activation-strip"><div class="activation-heading"><h3>${escape(p.name)} 正在使用的战技</h3><span>自动施放 · 最多 5 种</span></div><div class="activation-slots">${Array.from({length:5},(_,i)=>{const k=p.activeSkills[i];return button('active-slot',`<small>${i+1}</small>${k?skillIcon(k,helpers,p):'<span class="empty-slot">＋</span>'}<span>${k?escape(g.mercenarySkillText(p.mercenaryId,k)?.name||defs[k]?.name):'空位'}</span>`,String(i),'',false,`activation-slot ${slot===i?'chosen':''}`,`aria-label="选择第 ${i+1} 激活位"`);}).join('')}</div><p class="muted">先选激活位，再选战技。同行会根据自身距离、伤势和法力出招；停用保留等级。</p></section><div class="skills-workspace"><div class="skill-tree">${groups.filter(([,ids])=>ids.length).map(([name,ids])=>`<section><h3>${name}</h3><div class="skill-node-grid">${ids.map(k=>button('skill',`${skillIcon(k,helpers,p)}<span>${escape(g.mercenarySkillText(p.mercenaryId,k)?.name||defs[k].name)}</span><small>${p.skills[k]} / ${defs[k].rank}${p.activeSkills.includes(k)?' · 已激活':defs[k].passive?' · 被动':''}</small>`,k,'',false,`tree-node learned ${selected===k?'chosen':''}`)).join('')}</div></section>`).join('')}</div><div class="selected-detail" aria-live="polite">${info?`<article class="skill-detail"><div class="skill-heading">${skillIcon(selected,helpers,p)}<div><small>${defs[selected].passive?'被动':'战技'} · 等级 ${p.skills[selected]} / ${defs[selected].rank}</small><h3>${escape(info.name)}</h3></div></div><p>${escape(info.description)}</p><p class="muted">${escape(trainingReason(g,p,selected,safe)||'提升一级消耗 '+defs[selected].cost+' 技能点')}</p><div class="row">${button('train','提升一级',p.mercenaryId,selected,!!trainingReason(g,p,selected,safe))}${defs[selected].passive?'':p.activeSkills.includes(selected)?button('deactivate','停用 · 保留等级',p.mercenaryId,selected,!safe,'ghost'):button('activate',p.activeSkills[slot]?'替换 '+escape(g.mercenarySkillText(p.mercenaryId,p.activeSkills[slot])?.name):'激活到第 '+(slot+1)+' 位',p.mercenaryId,selected+'|'+slot,!safe,'primary')}</div></article>`:'<p>尚未掌握战技。</p>'}</div></div>${studyView(g,p,safe,helpers)}`;}
function rosterView(g,safe,helpers){const h=g.mercenaryState(),owned=Object.values(h.roster),initial=!h.initialContractUsed;return `${initial?`<section class="note-card"><h3>选一位旅伴</h3><p>赛芙留了一份初行契约。下面六位都以<span class="quality-uncommon-v23">精良</span>品阶加入，选一个合得来的人一起出发。</p></section><div class="companion-recruit-grid-v23">${Object.values(MERCENARY_ROSTER).map(v=>`<article class="merc-contract">${imagePortrait({...v,mercenaryId:v.id},helpers,'companion-recruit-portrait-v23')}<small class="quality-uncommon-v23">精良 · ${escape(g._mercenaryDeps.CLASSES[v.cls]?.name||v.cls)}</small><h3>${escape(v.name)}</h3><p>${escape(v.desc)}</p>${button('recruit','邀请 '+escape(v.name),v.id,'',!safe||!g.canRecruitMercenaryV18(v.id),'primary')}</article>`).join('')}</div>`:`<section class="note-card"><h3>新的同行契约</h3><p>下一位来赴约的旅人会是谁，还要等见面才知道。邀请后，人物、职业与品阶即刻确定。</p><div class="row">${button('recruit-random',`使用招募券 · 持有 ${h.ticketCount} 张`,'','',!safe||h.ticketCount<1||!g.canRecruitRandomMercenaryV23?.(),'primary')}</div></section>`}${owned.length?`<div class="companion-owned-grid-v23">${owned.map(p=>`<article class="merc-contract">${imagePortrait(p,helpers,'companion-recruit-portrait-v23')}<small style="color:${quality(p).color}">${quality(p).name} · ${escape(className(g,p))} · Lv.${p.level}${contractSuffix(p)}</small><h3>${escape(p.name)}</h3><p>${status(h,p)}</p>${button('select','查看人物',p.mercenaryId,'',false)}</article>`).join('')}</div>`:''}<p class="tip">最多三位受雇同行一起出战。艾莉娅随剧情同行，不占这三个位置。</p>`;}

export function mercenaryHTML(g,helpers={}){
 const {h,id,p}=chosen(g),safe=g.mercenarySafe(),u=syncActor(g,id),tab=!p||h.tab==='roster'?'roster':['equipment','skills','growth'].includes(h.tab)?h.tab:'growth';
 const nav={equipment:'行囊',growth:'属性',skills:'技能',roster:'同行'};
 return `<div class="modal"><section class="panel fade companion-panel-v23" data-companion-id="${escape(id||'')}" role="dialog" aria-modal="true" aria-labelledby="companion-title-v23"><header class="panel-head"><div><small>同行者 · 旅人手记</small><h2 id="companion-title-v23">${tab==='roster'?'同行契约':escape(p.name)}</h2></div><button data-act="resume">返回 ×</button></header>${Object.keys(h.roster).length?`<nav class="companion-switch-v23 tabs" aria-label="选择同行者">${Object.values(h.roster).map(a=>button('select',`${escape(a.name)}<small>${escape(className(g,a))} · ${quality(a).name}${contractSuffix(a)}</small>`,a.mercenaryId,'',false,id===a.mercenaryId?'on':'',`aria-pressed="${id===a.mercenaryId}"`)).join('')}</nav>`:''}<nav class="tabs" aria-label="人物栏目">${Object.entries(nav).map(([k,v])=>button('tab',v,k,'',!p&&k!=='roster',k===tab?'on':'',`aria-pressed="${k===tab}"`)).join('')}</nav><div class="panel-body"><div class="summary"><span>金币 <b>${g.p.gold}</b></span><span>同时出战 <b>${h.activeIds.length} / 3</b></span>${p&&tab!=='roster'?`<span style="color:${quality(p).color}">${quality(p).name} · ${escape(className(g,p))} · Lv.${p.level}</span><span>属性点 <b>${p.ap}</b></span><span>经验 ${p.level>=sagaLevelCapV25(g)?'已达上限':Math.floor(p.xp)+' / '+(70+p.level*40)}</span>`:''}</div>${!safe?'<p class="companion-readonly-v23">这里可查看行装；回到安全处后可加点、换装和招募。</p>':''}${u.notice?`<p class="companion-result-v23" role="status">${escape(u.notice)}</p>`:''}${tab==='roster'?rosterView(g,safe,helpers):tab==='equipment'?equipmentView(g,p,safe,helpers):tab==='skills'?skillsView(g,p,safe,helpers):attributesView(g,p,safe,helpers)}</div></section></div>`;
}

export function handleMercenaryAction(g,element){
 const d=element?.dataset||element||{},action=d.merc;if(!action||element?.disabled)return false;const a=d.mercArg||'',b=d.mercArg2||'',{h,p}=chosen(g),u=syncActor(g,p?.mercenaryId);
 if(action==='select'){if(!h.roster[a])return false;h.selectedId=a;h.tab='growth';h.gear=null;h.skill=null;syncActor(g,a);return true;}
 if(action==='tab'){if(!['roster','growth','equipment','skills'].includes(a))return false;h.tab=a;u.confirm=null;return true;}
 if(action==='cancel-confirm'){u.confirm=null;return true;}
 if(action==='recruit'){const ok=g.recruitMercenary(a);if(ok){h.tab='growth';syncActor(g,h.selectedId);}return !!ok;}
 if(action==='recruit-random'){const ok=g.recruitRandomMercenaryV23?.();if(ok){h.tab='growth';syncActor(g,h.selectedId);}return !!ok;}
 if(!p)return false;
 if(action==='skill'){if(!(p.skills[a]>0))return false;h.skill=a;return true;}
 if(action==='gear'){if(!a.startsWith('empty:')&&!Object.values(p.gear).some(i=>i?.id===a)&&!g.p.bag.some(i=>i.id===a))return false;h.gear=a;return true;}
 if(action==='active-slot'){const n=Number(a);if(!Number.isInteger(n)||n<0||n>4)return false;u.activeSlot=Math.min(n,p.activeSkills.length,4);return true;}
 // Actor-specific DOM actions must match the visible actor. A stale button cannot
 // spend points, move equipment, or dismiss someone selected by a later render.
 if(a!==p.mercenaryId)return false;
 if(action==='dismiss'||action==='request-reset'){if(!g.mercenarySafe())return false;if(action==='request-reset'&&!['attributeReset','skillReset'].includes(b))return false;u.confirm={kind:action==='dismiss'?'dismiss':'reset',id:a,item:b};return true;}
 if(action==='confirm-dismiss'){if(u.confirm?.kind!=='dismiss'||u.confirm.id!==a)return false;const name=p.name,count=Object.values(p.gear).filter(Boolean).length,ok=g.dismissMercenaryV23?.(a);if(ok){u.confirm=null;h.tab='roster';syncActor(g,h.selectedId);local(g).notice=`已与 ${name} 告别，${count} 件装备收回了行囊。`;}return !!ok;}
 if(action==='confirm-reset'){if(u.confirm?.kind!=='reset'||u.confirm.id!==a||u.confirm.item!==b)return false;const ok=g.resetMercenary?.(a,b);if(ok)u.confirm=null;return !!ok;}
 if(action==='buyBook')return !!g.buyMercenaryBook();
 if(action==='teach'){const k=g.teachMercenary(a);if(k)h.skill=typeof k==='string'?k:k.skill;return !!k;}
 if(action==='deploy')return !!g.deployMercenary(a);
 if(action==='withdraw')return !!g.withdrawMercenaryV18(a);
 if(action==='treat')return !!g.treatMercenary(a);
 if(action==='allocate')return !!g.allocateMercenary(a,b);
 if(action==='train')return !!g.trainMercenary(a,b);
 if(action==='deactivate')return !!g.deactivateMercenarySkill(a,b);
 if(action==='activate'){const [k,slot]=b.split('|');return !!g.activateMercenarySkill(a,k,+slot);}
 if(action==='equip'){const [id,slot]=b.split('|');return !!g.equipMercenary(a,id,slot);}
 if(action==='unequip')return !!g.unequipMercenary(a,b);
 return false;
}

export function renderMercenaryPaperdoll(g,bank,{drawHero,footShadow},root=globalThis.document){const canvas=root?.querySelector('#mercenary-paperdoll'),{p}=chosen(g);if(!canvas||!p)return;const c=canvas.getContext('2d');if(!c)return;c.clearRect(0,0,canvas.width,canvas.height);c.imageSmoothingEnabled=false;footShadow(c,180,335,75,.4);const actor={...p,x:180,y:335,moving:false,attackAnim:0,angle:0};if(!drawIdentityActorV18(c,bank,actor,0,{size:230}))drawHero(c,bank,p,180,335,0,{size:230,moving:false,attack:0,angle:0});}
